<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<div class="page-heading"><div><h1>Categories</h1><p>Manage catalog groupings.</p></div><a class="button" href="/admin/categories/create">Add category</a></div>
<?php if($flash):?><p class="flash flash-<?= $e($flash['type']) ?>" role="status"><?= $e($flash['message']) ?></p><?php endif;?>
<section class="panel table-wrap"><table><thead><tr><th>Name</th><th>Slug</th><th>Products</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $item):?><tr><td><?= $e($item['name']) ?></td><td><code><?= $e($item['slug']) ?></code></td><td><?= $e($item['product_count']) ?></td><td><span class="badge <?= (int)$item['is_active']===1?'active':'hidden' ?>"><?= (int)$item['is_active']===1?'Active':'Hidden' ?></span></td><td class="actions"><a href="/admin/categories/<?= $e($item['id']) ?>/edit">Edit</a><form method="post" action="/admin/categories/<?= $e($item['id']) ?>/status"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="is_active" value="<?= (int)$item['is_active']===1?'0':'1' ?>"><button class="link-button" type="submit"><?= (int)$item['is_active']===1?'Hide':'Activate' ?></button></form><form method="post" action="/admin/categories/<?= $e($item['id']) ?>/delete" data-confirm="Delete this category? This is blocked while products are assigned."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><button class="link-button danger" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if($categories===[]):?><p>No categories yet.</p><?php endif;?></section>
